let D;const $=id=>document.getElementById(id),pct=x=>typeof x==='number'?(x*100).toLocaleString('pt-BR',{maximumFractionDigits:1,minimumFractionDigits:1})+'%':'—',esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={MAT:'Matemática',PORT:'Língua Portuguesa',ING:'Língua Inglesa',HIST:'História',GEO:'Geografia',CIE:'Ciências',FIN:'Educação Financeira'};
const score=(r,s)=>s?r.subjects[s]:r.score;
const avg=(rs,s)=>{let v=rs.filter(r=>r.participation>0&&typeof score(r,s)==='number').map(r=>score(r,s));return v.length?v.reduce((a,b)=>a+b,0)/v.length:null};
const bar=(label,v)=>`<div class="barrow"><span>${esc(label)}</span><div class="track"><div class="bar" style="width:${v===null?0:v*100}%"></div></div><strong>${pct(v)}</strong></div>`;
function render(){let t=+$('term').value,c=$('class').value,s=$('subject').value;let p=D.panels[t-1];$('cards').innerHTML=['Participação geral','Acertos gerais','Participação · prova física','Acertos · prova física'].map((a,i)=>`<div class="card"><span>${a}</span><div class="value">${pct(p[i]/100)}</div><small>Painel geral · ${t}º bimestre</small></div>`).join('');let rows=D.students.filter(r=>r.term===t&&(!c||r.class===c));let classes=[...new Set(rows.map(r=>r.class))].sort();$('classbars').innerHTML=classes.map(k=>bar(k,avg(rows.filter(r=>r.class===k),s))).join('');let av=[1,2,3].map(n=>avg(D.students.filter(r=>r.term===n&&(!c||r.class===c)),s));$('termbars').innerHTML=av.map((v,i)=>bar((i+1)+'º bim.',v)).join('');$('trend').textContent=av[1]!==null&&av[2]!==null?`Variação do 2º para o 3º bimestre: ${((av[2]-av[1])*100).toLocaleString('pt-BR',{maximumFractionDigits:1,minimumFractionDigits:1})} pontos percentuais. Os grupos de estudantes podem mudar entre os períodos.`:'Dados insuficientes neste recorte.';
let qs=D.questions.filter(q=>q.term===t&&(!c||String(q.year).startsWith(c[0]))&&(!s||String(q.subject).toLocaleUpperCase('pt-BR').includes(({MAT:'MATEMÁTICA',PORT:'PORTUGUESA',ING:'INGLESA',HIST:'HISTÓRIA',GEO:'GEOGRAFIA',CIE:'CIÊNCIAS',FIN:'FINANCEIRA'})[s]||s))).sort((a,b)=>a.score-b.score);let link=(u,l)=>typeof u==='string'&&/^https:\/\//.test(u)?`<a href="${esc(u)}" target="_blank" rel="noopener">${l}</a>`:'';$('questions').innerHTML=qs.map(q=>`<tr><td>${esc(q.year)}</td><td>${esc(q.subject)}</td><td class="${q.score<.5?'low':''}">${pct(q.score)}</td><td>${esc(q.skill)}</td><td>${link(q.lesson,'Aula')} ${link(q.question,'Questão')}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum descritor disponível neste recorte.</td></tr>';
let query=$('search').value.toLocaleLowerCase('pt-BR');$('studentrows').innerHTML=rows.filter(r=>String(r.name).toLocaleLowerCase('pt-BR').includes(query)).sort((a,b)=>a.class.localeCompare(b.class)||a.name.localeCompare(b.name)).map(r=>{let prev=D.students.find(x=>x.term===t-1&&x.id===r.id),v=score(r,s),pv=prev?score(prev,s):null,d=r.participation>0&&prev?.participation>0&&typeof v==='number'&&typeof pv==='number'?((v-pv)*100).toLocaleString('pt-BR',{maximumFractionDigits:1,minimumFractionDigits:1})+' p.p.':'—';return `<tr><td>${esc(r.name)}</td><td>${esc(r.class)}</td><td>${pct(r.participation)}</td><td>${r.participation>0?pct(v):'Sem participação'}</td><td>${d}</td></tr>`}).join('');}
fetch('data.json').then(r=>r.json()).then(d=>{D=d;for(const c of [...new Set(d.students.map(r=>r.class))].sort())$('class').add(new Option(c,c));for(const s of [...new Set(d.students.flatMap(r=>Object.keys(r.subjects)))].sort())$('subject').add(new Option(names[s]||s,s));for(const id of ['term','class','subject','search'])$(id).addEventListener(id==='search'?'input':'change',render);render()}).catch(()=>{$('cards').textContent='Não foi possível carregar os dados. Atualize a página.'});
